import re,glob,sys
test='src/orchestration/chatOrchestrator.test.ts'
lines=open(test).read().split('\n')
def find(title):
    hits=[i+1 for i,l in enumerate(lines) if re.search(r"\bit\((['\"`])"+re.escape(title)+r"\1",l)]
    return hits
pat=re.compile(r"\[validated by:? ([^\]]+?)\]\(([^)]*chatOrchestrator\.test\.ts)#L(\d+)\)")
for f in glob.glob('specs/**/*.md',recursive=True)+glob.glob('*.md')+glob.glob('docs/**/*.md',recursive=True)+glob.glob('.specify/*.md'):
    s=open(f).read()
    def rep(m):
        h=find(m.group(1))
        if len(h)!=1: print('UNMAPPED',f,m.group(1),h); return m.group(0)
        if str(h[0])!=m.group(3): print('moved',f,m.group(1),m.group(3),'->',h[0])
        return f"[validated by{':' if 'validated by:' in m.group(0) else ''} {m.group(1)}]({m.group(2)}#L{h[0]})"
    n=pat.sub(rep,s)
    if n!=s: open(f,'w').write(n)
EOF
